import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:hydrowin/app/cloud_scope.dart';
import 'package:hydrowin/core/constants/app_constants.dart';
import 'package:hydrowin/domain/models/developer_settings.dart';
import 'package:hydrowin/domain/models/network_settings.dart';
import 'package:go_router/go_router.dart';

/// Единый экран: Wi‑Fi / GSM блока + адрес сервера API.
/// Доступен только администратору клиентской организации (не производителю).
class NetworkSettingsScreen extends StatefulWidget {
  const NetworkSettingsScreen({super.key});

  @override
  State<NetworkSettingsScreen> createState() => _NetworkSettingsScreenState();
}

class _NetworkSettingsScreenState extends State<NetworkSettingsScreen> {
  static const _defaultHost = '5.165.27.141';
  static const _defaultPort = 8090;

  bool _loading = true;
  bool _allowed = false;

  late NetworkSettings _network;
  late TextEditingController _host;
  late TextEditingController _apiPort;
  late TextEditingController _blockPort;
  late TextEditingController _apiPath;
  late TextEditingController _wifiSsid;
  late TextEditingController _wifiPass;
  late TextEditingController _gsmApn;
  late TextEditingController _gsmUser;
  late TextEditingController _gsmPass;
  bool _useCustom = false;
  bool _obscureWifi = true;
  bool _obscureGsm = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _init());
  }

  Future<void> _init() async {
    final scope = CloudScope.of(context);
    final admin = await scope.auth.isAdmin();
    var manufacturer = false;
    if (admin && !await scope.tokens.isDemoSession()) {
      try {
        final me = await scope.organizations.fetchMe();
        manufacturer = me.isManufacturer;
      } catch (_) {}
    }

    if (!mounted) return;
    if (!admin || manufacturer) {
      setState(() {
        _loading = false;
        _allowed = false;
      });
      return;
    }

    _network = scope.networkSettings.load();
    final dev = scope.developerSettings.load();
    final host = dev.serverHost.trim().isEmpty ? _defaultHost : dev.serverHost;
    _host = TextEditingController(text: host);
    _apiPort = TextEditingController(text: '${dev.apiPort}');
    _blockPort = TextEditingController(text: '${dev.BLOCKPort}');
    _apiPath = TextEditingController(text: dev.apiPath);
    _useCustom = dev.useCustomServer;
    _wifiSsid = TextEditingController(text: _network.wifiSsid);
    _wifiPass = TextEditingController(text: _network.wifiPassword);
    _gsmApn = TextEditingController(text: _network.gsmApn);
    _gsmUser = TextEditingController(text: _network.gsmApnUser);
    _gsmPass = TextEditingController(text: _network.gsmApnPass);

    setState(() {
      _loading = false;
      _allowed = true;
    });
  }

  @override
  void dispose() {
    if (_allowed) {
      _host.dispose();
      _apiPort.dispose();
      _blockPort.dispose();
      _apiPath.dispose();
      _wifiSsid.dispose();
      _wifiPass.dispose();
      _gsmApn.dispose();
      _gsmUser.dispose();
      _gsmPass.dispose();
    }
    super.dispose();
  }

  NetworkSettings _collectNetwork() {
    return _network.copyWith(
      wifiSsid: _wifiSsid.text.trim(),
      wifiPassword: _wifiPass.text,
      gsmApn: _gsmApn.text.trim(),
      gsmApnUser: _gsmUser.text.trim(),
      gsmApnPass: _gsmPass.text,
    );
  }

  Future<void> _saveLinkType(String linkType) async {
    _network = _collectNetwork().copyWith(BLOCKLinkType: linkType);
    await CloudScope.of(context).networkSettings.save(_network);
    if (mounted) setState(() {});
  }

  Future<void> _saveAll() async {
    final scope = CloudScope.of(context);
    _network = _collectNetwork();
    await scope.networkSettings.save(_network);

    final host = _host.text.trim().isEmpty ? _defaultHost : _host.text.trim();
    final port = int.tryParse(_apiPort.text.trim()) ?? _defaultPort;
    final updated = DeveloperSettings(
      serverHost: host,
      apiPort: port,
      BLOCKPort: int.tryParse(_blockPort.text.trim()) ?? 80,
      apiPath: _apiPath.text.trim().isEmpty ? '/v1' : _apiPath.text.trim(),
      useCustomServer: _useCustom,
    );
    await scope.developerSettings.save(updated);
    scope.api.baseUrl = scope.serverConfig.resolveApiBaseUrl();

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'Сохранено.\n'
          'Приложение: ${scope.api.baseUrl}\n'
          'Для блока — «Скопировать команды» → USB Serial',
        ),
      ),
    );
    setState(() {});
  }

  Future<void> _resetToProduction() async {
    setState(() {
      _useCustom = false;
      _host.text = _defaultHost;
      _apiPort.text = '$_defaultPort';
      _apiPath.text = '/v1';
    });
    await _saveAll();
  }

  Future<void> _copyBlockCommands() async {
    final net = _collectNetwork();
    final host = _useCustom
        ? (_host.text.trim().isEmpty ? _defaultHost : _host.text.trim())
        : _defaultHost;
    final port = _useCustom
        ? (int.tryParse(_apiPort.text.trim()) ?? _defaultPort)
        : _defaultPort;

    final cmds = net.toBlockUsbCommands(apiHost: host, apiPort: port);
    await Clipboard.setData(ClipboardData(text: cmds));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'Команды скопированы. Вставьте в Serial Monitor ESP32 (115200):\n$cmds',
        ),
        duration: const Duration(seconds: 6),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (!_allowed) {
      return Scaffold(
        appBar: AppBar(
          title: const Text('Настройка блока и сети'),
          leading: BackButton(onPressed: () => context.pop()),
        ),
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
              'Доступно только администратору предприятия.\n'
              'Учётная запись производителя (HydroMaker) эту настройку не видит.',
              textAlign: TextAlign.center,
            ),
          ),
        ),
      );
    }

    final serverUrl = CloudScope.of(context).serverConfig.resolveApiBaseUrl();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Настройка блока и сети'),
        leading: BackButton(onPressed: () => context.pop()),
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          Text(
            'Как блок передаёт данные на сервер',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 8),
          RadioListTile<String>(
            title: const Text('Wi‑Fi'),
            subtitle: const Text('Блок в зоне Wi‑Fi'),
            value: AppConstants.BLOCKLinkWifi,
            groupValue: _network.BLOCKLinkType,
            onChanged: (v) => v == null ? null : _saveLinkType(v),
          ),
          RadioListTile<String>(
            title: const Text('GSM (SIM)'),
            subtitle: const Text('Модем SIM900A / сотовая сеть'),
            value: AppConstants.BLOCKLinkGsm,
            groupValue: _network.BLOCKLinkType,
            onChanged: (v) => v == null ? null : _saveLinkType(v),
          ),

          if (_network.isWifi) ...[
            const Divider(height: 32),
            Text(
              'Wi‑Fi блока (на объекте)',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 8),
            TextField(
              controller: _wifiSsid,
              decoration: const InputDecoration(
                labelText: 'SSID сети',
                hintText: 'SVEXC',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _wifiPass,
              obscureText: _obscureWifi,
              decoration: InputDecoration(
                labelText: 'Пароль Wi‑Fi',
                border: const OutlineInputBorder(),
                suffixIcon: IconButton(
                  icon: Icon(
                    _obscureWifi ? Icons.visibility : Icons.visibility_off,
                  ),
                  onPressed: () =>
                      setState(() => _obscureWifi = !_obscureWifi),
                ),
              ),
            ),
          ],

          if (_network.isGsm) ...[
            const Divider(height: 32),
            Text(
              'GSM / APN SIM-карты',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 8),
            TextField(
              controller: _gsmApn,
              decoration: const InputDecoration(
                labelText: 'APN',
                hintText: 'internet.beeline.ru',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _gsmUser,
              decoration: const InputDecoration(
                labelText: 'APN user',
                hintText: 'beeline',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _gsmPass,
              obscureText: _obscureGsm,
              decoration: InputDecoration(
                labelText: 'APN password',
                border: const OutlineInputBorder(),
                suffixIcon: IconButton(
                  icon: Icon(
                    _obscureGsm ? Icons.visibility : Icons.visibility_off,
                  ),
                  onPressed: () => setState(() => _obscureGsm = !_obscureGsm),
                ),
              ),
            ),
          ],

          const Divider(height: 32),
          Text(
            'Сервер API',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 4),
          Text(
            'По умолчанию: http://$_defaultHost:$_defaultPort/v1\n'
            'Сейчас приложение: $serverUrl',
            style: Theme.of(context).textTheme.bodySmall,
          ),
          const SizedBox(height: 8),
          SwitchListTile(
            contentPadding: EdgeInsets.zero,
            title: const Text('Другой сервер'),
            subtitle: const Text(
              'Выкл = всегда прод $_defaultHost. '
              'Вкл = свой IP (локальный Docker и т.п.)',
            ),
            value: _useCustom,
            onChanged: (v) => setState(() {
              _useCustom = v;
              if (v && _host.text.trim().isEmpty) {
                _host.text = _defaultHost;
              }
            }),
          ),
          const SizedBox(height: 8),
          TextField(
            controller: _host,
            enabled: _useCustom,
            decoration: const InputDecoration(
              labelText: 'IP или хост сервера',
              hintText: _defaultHost,
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _apiPort,
            enabled: _useCustom,
            keyboardType: TextInputType.number,
            decoration: const InputDecoration(
              labelText: 'Порт API',
              hintText: '8090',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _apiPath,
            enabled: _useCustom,
            decoration: const InputDecoration(
              labelText: 'Путь API',
              hintText: '/v1',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _blockPort,
            decoration: const InputDecoration(
              labelText: 'Порт блока (справочно)',
              hintText: '80',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 12),
          OutlinedButton.icon(
            onPressed: _resetToProduction,
            icon: const Icon(Icons.cloud_done),
            label: const Text('Сбросить сервер на прод ($_defaultHost)'),
          ),
          const SizedBox(height: 16),
          FilledButton(
            onPressed: _saveAll,
            child: const Text('СОХРАНИТЬ'),
          ),
          const SizedBox(height: 12),
          OutlinedButton.icon(
            onPressed: _copyBlockCommands,
            icon: const Icon(Icons.copy_all),
            label: const Text('Скопировать команды для блока (USB)'),
          ),
          const SizedBox(height: 8),
          Text(
            'Приложение хранит настройки у себя. '
            'Чтобы ESP32 начал использовать Wi‑Fi / APN / сервер — '
            'скопируйте команды и вставьте в Serial Monitor (115200), '
            'затем перезагрузите блок.',
            style: Theme.of(context).textTheme.bodySmall,
          ),
        ],
      ),
    );
  }
}
